            bool hasParams = ps.Length > 0 && ps[ps.Length - 1].IsDefined(typeof(ParamArrayAttribute), false);
            int fixedCount = hasParams ? ps.Length - 1 : ps.Length;
            if (!hasParams && args.Length > fixedCount) return -1;
